import numpy as np
from scipy.optimize import brentq
from scipy.special import expit
from model import _occupation
def calc(e,t,V):
 z,w=np.polynomial.legendre.leggauss(1000); th=np.pi*(z+1)/2; wt=w*np.pi/2; E=-2*np.cos(th); s=np.sin(th); rho=s/np.pi
 surf=(E-2j*s)/2; A=-np.imag(1/(E-e-V*V*surf))/np.pi
 total=np.sum(wt*2*s*A*expit(-E/t)); bs=[]
 def g(x): return (x-np.sign(x)*np.sqrt(x*x-4))/2
 def den(x):return x-e-V*V*g(x)
 for lo,hi in [(-2-abs(e)-2*V,-2-1e-10),(2+1e-10,2+abs(e)+2*V)]:
  if den(lo)*den(hi)<0:
   b=brentq(den,lo,hi); gp=(1-abs(b)/np.sqrt(b*b-4))/2; wd=1/(1-V*V*gp)
   chain=V*V*wd*np.sum(wt*2*s*rho*expit(-E/t)/(b-E)**2)
   nb=wd*(wd+chain); total+=nb; bs.append((b,wd,chain,nb,wd*expit(-b/t)))
 return total,bs
for V in [2.4,3.2]:print(V,calc(.3,.2,V),_occupation(.3,.2,V))
